// Panel manual (generated by Clipbook). Data: data.js (window.MANUAL).
// Jump addresses for the HMI: index.html?lang=de#/fault/12 · #/component/<id> · #/
// Nothing scrolls: chapters are cut into screens that fit the space the page really gets
// (text left, picture right), lists are paged. Swipe or the buttons move between screens.
(function () {
  "use strict";
  const M = window.MANUAL;
  const LANGS = M.languages || ["de"];
  const lang = (() => {
    const q = new URLSearchParams(location.search).get("lang");
    return LANGS.includes(q) ? q : LANGS[0];
  })();
  document.documentElement.lang = lang;

  const UI = {
    de: { help: "Hilfe", faultsSub: "Nummer eingeben", maintSub: "Was ist wann fällig", partsSub: "Teilenummern",
      comps: "Baugruppen dieser Maschine", enter: "Störungsnummer", all: "Alle Störungen",
      toComp: "Zur Baugruppe", noPage: "Zu Störung {c} gibt es keine Hilfeseite.",
      noPageSub: "Bitte Nummer prüfen oder in der Liste suchen.", prev: "Zurück", next: "Weiter",
      fault: "Störung", unknown: "Seite nicht gefunden", fallback: "Diese Seite gibt es nur auf {l}.",
      empty: "Zu dieser Baugruppe gibt es keinen Text.", zoom: "Zum Schließen tippen", pages: "Kapitel",
      page1: "Kapitel", chapter: "Kapitel" },
    en: { help: "Help", faultsSub: "Enter number", maintSub: "What is due when", partsSub: "Part numbers",
      comps: "Assemblies of this machine", enter: "Fault number", all: "All faults",
      toComp: "Go to assembly", noPage: "There is no help page for fault {c}.",
      noPageSub: "Please check the number or search the list.", prev: "Back", next: "Next",
      fault: "Fault", unknown: "Page not found", fallback: "This page is only available in {l}.",
      empty: "There is no text for this assembly.", zoom: "Tap to close", pages: "chapters",
      page1: "chapter", chapter: "Chapter" },
    it: { help: "Aiuto", faultsSub: "Inserire numero", maintSub: "Cosa e quando", partsSub: "Codici ricambio",
      comps: "Gruppi di questa macchina", enter: "Numero guasto", all: "Tutti i guasti",
      toComp: "Al gruppo", noPage: "Nessuna pagina di aiuto per il guasto {c}.",
      noPageSub: "Controllare il numero o cercare nella lista.", prev: "Indietro", next: "Avanti",
      fault: "Guasto", unknown: "Pagina non trovata", fallback: "Questa pagina è disponibile solo in {l}.",
      empty: "Nessun testo per questo gruppo.", zoom: "Tocca per chiudere", pages: "capitoli",
      page1: "capitolo", chapter: "Capitolo" },
  };
  const LANG_NAME = { de: "Deutsch", en: "English", it: "Italiano" };
  const t = (k) => (UI[lang] || UI.de)[k] || UI.de[k];
  const L = (k) => ((M.labels || {})[lang] || {})[k] || ((M.labels || {})[LANGS[0]] || {})[k] || k;
  const tr = (v) => (v && typeof v === "object" ? v[lang] || v[LANGS[0]] || Object.values(v)[0] || "" : v || "");
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  const lines = (s) => tr(s).split("\n").map((x) => x.trim()).filter(Boolean);

  // line icons, 24×24 (same set as the desktop app)
  const ICON = {
    home: '<path d="M4 11l8-7 8 7v9h-5v-6H9v6H4z"/>',
    left: '<path d="M15 5l-7 7 7 7"/>',
    right: '<path d="M9 5l7 7-7 7"/>',
    alert: '<path d="M12 3.5l9.5 17h-19z"/><path d="M12 10v4.5M12 17.5v.01"/>',
    wrench: '<path d="M14.7 6.3a4 4 0 0 0-5.3 5.3l-5.9 5.9a1.5 1.5 0 0 0 2.1 2.1l5.9-5.9a4 4 0 0 0 5.3-5.3l-2.6 2.6-2.4-.6-.6-2.4z"/>',
    package: '<path d="M12 3l8 4.5v9L12 21l-8-4.5v-9z"/><path d="M4 7.5l8 4.5 8-4.5M12 12v9"/>',
  };
  const svg = (body) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
    stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${body}</svg>`;
  const icon = (n) => svg(ICON[n] || ICON.alert);

  const comps = M.components || [];
  const comp = (id) => comps.find((c) => c.id === id);
  const faults = (M.faults || []).slice().sort((a, b) => (parseInt(a.code, 10) || 1e9) - (parseInt(b.code, 10) || 1e9));
  const fault = (code) => faults.find((f) => String(f.code) === String(code));
  const color = (id) => (comp(id) || {}).color || "#5d6b78";
  // general chapters (Allgemeines, Wartung & Störungen) are no assembly: no tag for them in lists
  const assembly = (id) => { const c = comp(id); return c && !["general", "service"].includes(c.slot) ? c : null; };
  const pagesOf = (c) => (c.pages || {})[lang] || (c.pages || {})[LANGS[0]] || [];
  const fallbackOf = (c) => (c.fallback || {})[lang];

  const view = document.getElementById("view");
  const go = (h) => { location.hash = h; };

  // --- touch helpers ----------------------------------------------------------
  let swiped = false;  // a swipe must not also count as a tap
  function swipe(el, next, prev) {
    let x0 = null, y0 = 0;
    el.addEventListener("pointerdown", (e) => { x0 = e.clientX; y0 = e.clientY; });
    el.addEventListener("pointerup", (e) => {
      if (x0 === null) return;
      const dx = e.clientX - x0, dy = e.clientY - y0;
      x0 = null;
      if (Math.abs(dx) > 70 && Math.abs(dx) > Math.abs(dy) * 1.5) {
        swiped = true;
        setTimeout(() => { swiped = false; }, 0);
        (dx < 0 ? next : prev)();
      }
    });
  }

  // --- paged lists: as many items as fit, ‹ 1/3 › below instead of scrolling ----
  const listPage = {};  // remembered page per list, so "back" returns to the same page
  function paged(key, items, { cols = 1, rowH = 76, gap = 10 } = {}) {
    return {
      html: `<div class="paged"><div class="pgrid" data-key="${key}"></div><div class="mini-pager"></div></div>`,
      mount() {
        const grid = view.querySelector(`.pgrid[data-key="${key}"]`);
        const bar = grid.nextElementSibling;
        // measure with the pager visible, so a list that needs pages still fits
        bar.innerHTML = `<button class="nav">${icon("left")}</button>`;
        let rows = Math.max(1, Math.floor((grid.clientHeight + gap) / (rowH + gap)));
        if (items.length <= rows * cols) {
          bar.innerHTML = "";
          bar.hidden = true;
          rows = Math.max(1, Math.floor((grid.clientHeight + gap) / (rowH + gap)));
        }
        const per = rows * cols;
        const count = Math.max(1, Math.ceil(items.length / per));
        grid.style.gridTemplateColumns = `repeat(${cols}, minmax(0, 1fr))`;
        grid.style.gridAutoRows = `${rowH}px`;
        grid.style.gap = `${gap}px`;
        const show = (p) => {
          p = Math.max(0, Math.min(count - 1, p));
          listPage[key] = p;
          grid.innerHTML = items.slice(p * per, (p + 1) * per).join("");
          if (count < 2) return;
          bar.innerHTML = `<button class="nav" ${p === 0 ? "disabled" : ""} data-p="${p - 1}">${icon("left")}</button>
             <span>${p + 1} / ${count}</span>
             <button class="nav" ${p === count - 1 ? "disabled" : ""} data-p="${p + 1}">${icon("right")}</button>`;
          for (const b of bar.querySelectorAll("[data-p]")) b.onclick = () => show(Number(b.dataset.p));
        };
        show(listPage[key] || 0);
        swipe(grid, () => show((listPage[key] || 0) + 1), () => show((listPage[key] || 0) - 1));
      },
    };
  }

  const row = (href, badge, main, sub = "", style = "") =>
    `<button class="row" data-go="${href}"><span class="code" ${style}>${badge}</span>
      <span class="main">${main}${sub ? `<small>${sub}</small>` : ""}</span><span class="chev">›</span></button>`;

  // --- pages ---------------------------------------------------------------
  function home() {
    const task = (href, cls, ic, name, sub) =>
      `<button class="tile task ${cls}" data-go="${href}">${icon(ic)}<div><div class="name">${esc(name)}</div><div class="sub">${esc(sub)}</div></div></button>`;
    const shown = comps.filter((c) => pagesOf(c).length || faults.some((f) => f.component === c.id));
    const tiles = shown.map((c) => `<button class="tile comp" style="--c:${c.color}" data-go="#/component/${c.id}">${svg(c.icon)}
      <div><div class="name">${esc(tr(c.title))}</div><div class="sub">${compSub(c)}</div></div></button>`);
    const list = paged("home", tiles, { cols: 4, rowH: 100, gap: 12 });
    return {
      title: `${t("help")} · ${esc(M.machine || "")}`,
      html: `<div class="fill">
        <div class="grid tasks">
          ${task("#/faults", "fault", "alert", L("faults"), t("faultsSub"))}
          ${task("#/maintenance", "", "wrench", L("maintenance"), t("maintSub"))}
          ${task("#/parts", "", "package", L("spare_parts"), t("partsSub"))}
        </div>
        <p class="section">${t("comps")}</p>${list.html}</div>`,
      after: list.mount,
    };
  }

  function compSub(c) {
    const n = pagesOf(c).length;
    if (n) return `${n} ${t(n === 1 ? "page1" : "pages")}`;
    const f = faults.filter((x) => x.component === c.id).length;
    return f ? `${f} ${L("faults")}` : "";
  }

  function faultRows(filter) {
    return faults.filter((f) => !filter || f.component === filter).map((f) =>
      row(`#/fault/${encodeURIComponent(f.code)}`, esc(f.code), esc(tr(f.message)),
          esc(tr((comp(f.component) || {}).title)), `style="--c:${color(f.component)}"`));
  }

  function faultSearch() {
    const keys = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "⌫", "0", "OK"];
    const list = paged("faults", faultRows());
    return {
      title: esc(L("faults")), up: "#/",
      html: `<div class="split-pad">
        <div class="pad"><div class="display" id="num" data-ph="${t("enter")}"></div>
          ${keys.map((k) => `<button data-key="${k}" class="${k === "OK" ? "ok" : ""}">${k}</button>`).join("")}</div>
        ${list.html}</div>`,
      after() {
        list.mount();
        const num = document.getElementById("num");
        for (const b of view.querySelectorAll("[data-key]")) {
          b.onclick = () => {
            const k = b.dataset.key;
            if (k === "⌫") num.textContent = num.textContent.slice(0, -1);
            else if (k === "OK") { if (num.textContent) go("#/fault/" + num.textContent); }
            else if (num.textContent.length < 6) num.textContent += k;
          };
        }
      },
    };
  }

  function faultPage(code) {
    const f = fault(code);
    if (!f) {
      return {
        title: `${t("fault")} ${esc(code)}`, up: "#/faults",
        html: `<div class="empty"><h2>${t("noPage").replace("{c}", esc(code))}</h2><p>${t("noPageSub")}</p>
          <button class="btn primary" data-go="#/faults">${t("all")}</button></div>`,
      };
    }
    const c = comp(f.component);
    return {
      title: `${t("fault")} ${esc(f.code)}`, up: "#/faults",
      html: `<div class="fill fault">
        <div class="fault-head"><span class="code" style="--c:${color(f.component)}">${esc(f.code)}</span>
          <div><h2>${esc(tr(f.message))}</h2>${c ? `<small>${esc(tr(c.title))}</small>` : ""}</div></div>
        <div class="cols">
          <div class="card warn"><h3>${esc(L("cause"))}</h3>${lines(f.cause).map((l) => `<div>${esc(l)}</div>`).join("")}</div>
          <div class="card"><h3>${esc(L("remedy"))}</h3><ol>${lines(f.remedy).map((l) => `<li>${esc(l)}</li>`).join("")}</ol></div>
        </div>
        ${c && pagesOf(c).length ? `<div class="actions"><button class="btn" style="--c:${c.color}" data-go="#/component/${c.id}">${svg(c.icon)} ${t("toComp")}: ${esc(tr(c.title))}</button></div>` : ""}</div>`,
    };
  }

  function componentPage(id, n, s) {
    const c = comp(id);
    if (!c) return notFound();
    if (n === "faults") {
      const list = paged(`faults-${id}`, faultRows(id));
      return { title: `${esc(tr(c.title))} · ${esc(L("faults"))}`, up: `#/component/${id}`,
        html: `<div class="fill">${list.html}</div>`, after: list.mount };
    }
    if (n === "maintenance") return maintenance(id);
    if (n == null) return chapterList(c);
    return reader(c, Number(n) - 1, s);
  }

  function chapterList(c) {
    const items = pagesOf(c).map((p, i) => row(`#/component/${c.id}/${i + 1}`, i + 1, esc(p.title),
                                                esc(p.group || ""), `style="--c:${c.color}"`));
    if (faults.some((f) => f.component === c.id)) {
      items.push(row(`#/component/${c.id}/faults`, icon("alert"), esc(L("faults"))));
    }
    if ((M.maintenance || []).some((m) => m.component === c.id)) {
      items.push(row(`#/component/${c.id}/maintenance`, icon("wrench"), esc(L("maintenance")), "", 'style="--c:#5d6b78"'));
    }
    if (!items.length) {
      return { title: esc(tr(c.title)), up: "#/", html: `<div class="empty"><p>${t("empty")}</p></div>` };
    }
    const list = paged(`chapters-${c.id}`, items, { cols: items.length > 6 ? 2 : 1 });
    return { title: esc(tr(c.title)), up: "#/", html: `<div class="fill">${list.html}</div>`, after: list.mount };
  }

  // --- chapter reader: cut into screens that fit ------------------------------
  function reader(c, i, s) {
    const pages = pagesOf(c);
    const p = pages[i];
    if (!p) return notFound();
    const fb = fallbackOf(c);
    const source = (fb ? `<div class="callout note">${t("fallback").replace("{l}", LANG_NAME[fb] || fb)}</div>` : "")
      + (p.group ? `<div class="crumb">${esc(p.group)}</div>` : "") + `<h2>${esc(p.title)}</h2>` + p.html;
    return {
      title: `${esc(tr(c.title))} · ${esc(p.title)}`, up: `#/component/${c.id}`,
      html: `<div class="reader"><div class="stage" id="stage"></div>
        <div class="pager">
          <button class="btn" id="prev">‹ ${t("prev")}</button>
          <div class="where"><div class="dots" id="dots"></div><small>${t("chapter")} ${i + 1} / ${pages.length}</small></div>
          <button class="btn primary" id="next">${t("next")} ›</button>
        </div></div>`,
      after() {
        const stage = document.getElementById("stage");
        const screens = layoutScreens(stage, blocksOf(source));
        let cur = s === "last" ? screens.length - 1 : Math.max(0, Math.min(screens.length - 1, (Number(s) || 1) - 1));
        const prevBtn = document.getElementById("prev"), nextBtn = document.getElementById("next");
        const show = () => {
          stage.replaceChildren(screens[cur]);
          document.getElementById("dots").innerHTML = screens.length < 2 ? "" :
            screens.map((_, k) => `<i class="${k === cur ? "on" : ""}"></i>`).join("");
          prevBtn.style.visibility = cur > 0 || i > 0 ? "" : "hidden";
          nextBtn.style.visibility = cur < screens.length - 1 || i < pages.length - 1 ? "" : "hidden";
          // keep the address in step without re-rendering (the HMI may read it)
          history.replaceState(null, "", `${location.search}#/component/${c.id}/${i + 1}/${cur + 1}`);
        };
        const next = () => {
          if (cur < screens.length - 1) { cur++; show(); } else if (i < pages.length - 1) go(`#/component/${c.id}/${i + 2}`);
        };
        const prev = () => {
          if (cur > 0) { cur--; show(); } else if (i > 0) go(`#/component/${c.id}/${i}/last`);
        };
        prevBtn.onclick = prev;
        nextBtn.onclick = next;
        swipe(stage, next, prev);
        show();
      },
    };
  }

  // page HTML -> top-level blocks; lists and tables become one block per item/row,
  // so they can break between screens (tables repeat their header row)
  const tableHead = {};
  let tableId = 0;
  function blocksOf(html) {
    const box = document.createElement("div");
    box.innerHTML = html;
    const out = [];
    for (const el of Array.from(box.children)) {
      const rows = el.classList.contains("tablewrap") ? el.querySelectorAll("tr") : [];
      if (rows.length > 3) {
        const id = String(++tableId);
        tableHead[id] = rows[0].outerHTML;
        for (const r of Array.from(rows).slice(1)) {
          const part = document.createElement("div");
          part.className = "tpart";
          part.dataset.table = id;
          part.dataset.row = r.outerHTML;
          out.push(part);
        }
        continue;
      }
      if ((el.tagName === "OL" || el.tagName === "UL") && el.children.length > 1) {
        let n = Number(el.getAttribute("start") || 1);
        const items = Array.from(el.children);
        items.forEach((li, k) => {
          const one = document.createElement(el.tagName);
          for (const a of el.attributes) one.setAttribute(a.name, a.value);
          if (el.tagName === "OL") one.setAttribute("start", String(n++));
          if (k < items.length - 1) one.classList.add("cont");
          one.appendChild(li);
          out.push(one);
        });
      } else {
        out.push(el);
      }
    }
    return out;
  }

  const isFigure = (el) => el.classList.contains("pic");
  const isHeading = (el) => /^H[2-6]$/.test(el.tagName) || el.classList.contains("crumb");

  function buildScreen(scr) {
    const el = document.createElement("div");
    el.className = "screen " + (scr.fig && scr.text.length ? scr.mode || "split" : scr.fig ? "fig-only" : "text-only");
    if (scr.text.length) {
      const col = document.createElement("div");
      col.className = "col-text";
      for (const b of scr.text) {
        if (!b.classList.contains("tpart")) { col.appendChild(b.cloneNode(true)); continue; }
        let table = col.lastElementChild;
        if (!table || table.dataset.table !== b.dataset.table) {
          table = document.createElement("div");
          table.className = "tablewrap";
          table.dataset.table = b.dataset.table;
          table.innerHTML = `<table><tbody>${tableHead[b.dataset.table]}</tbody></table>`;
          col.appendChild(table);
        }
        table.querySelector("tbody").insertAdjacentHTML("beforeend", b.dataset.row);
      }
      el.appendChild(col);
    }
    if (scr.fig) {
      const col = document.createElement("div");
      col.className = "col-fig";
      col.appendChild(scr.fig.cloneNode(true));
      el.appendChild(col);
    }
    return el;
  }

  // Greedy: fill text until the screen is full. A picture goes to the right of the text before it
  // (if that text still fits next to it), otherwise it starts the next screen; text after a
  // picture continues next to it. Headings are never left alone at the bottom of a screen.
  function layoutScreens(stage, blocks) {
    const probe = document.createElement("div");
    probe.className = "probe";
    stage.appendChild(probe);
    const fits = (scr) => {
      probe.replaceChildren(buildScreen(scr));
      const col = probe.querySelector(".col-text");
      return !col || col.scrollHeight <= col.clientHeight + 1;
    };
    // with a picture: picture gets 57 % of the width; if the text does not fit, text gets 55 %
    const fitSplit = (text, fig) => {
      for (const mode of ["split", "split-wide"]) {
        if (fits({ text, fig, mode })) return mode;
      }
      return null;
    };
    const screens = [];
    let cur = { text: [], fig: null, mode: null };
    const flush = () => {
      const carry = [];
      while (cur.text.length > 1 && isHeading(cur.text[cur.text.length - 1])) carry.unshift(cur.text.pop());
      if (cur.text.length || cur.fig) screens.push(cur);
      cur = { text: carry, fig: null, mode: null };
    };
    for (const b of blocks) {
      if (isFigure(b)) {
        const mode = cur.fig ? null : fitSplit(cur.text, b);
        if (mode) { cur.fig = b; cur.mode = mode; continue; }
        flush();
        if (cur.text.length) {
          const m2 = fitSplit(cur.text, b);
          if (!m2) { screens.push(cur); cur = { text: [], fig: null, mode: null }; } else cur.mode = m2;
        }
        cur.fig = b;
        continue;
      }
      const text = [...cur.text, b];
      if (!cur.fig && (fits({ text, fig: null }) || !cur.text.length)) { cur.text = text; continue; }
      if (cur.fig) {
        const mode = fitSplit(text, cur.fig);
        if (mode) { cur.text = text; cur.mode = mode; continue; }
        if (!cur.text.length) { cur.text = text; cur.mode = "split-wide"; continue; }  // one huge block
      }
      flush();
      cur.text.push(b);
    }
    if (cur.text.length || cur.fig) screens.push(cur);
    probe.remove();
    return (screens.length ? screens : [{ text: [], fig: null }]).map(buildScreen);
  }

  function maintenance(filter) {
    const rows = (M.maintenance || []).filter((r) => !filter || r.component === filter)
      .sort((a, b) => a.interval_days - b.interval_days);
    const items = rows.map((r) => `<div class="mrow"><div class="when">${esc(tr(r.interval))}
        ${assembly(r.component) && !filter ? `<span class="tag" style="--c:${color(r.component)}">${esc(tr(comp(r.component).title))}</span>` : ""}</div>
        <div><b>${esc(tr(r.task))}</b><small>${lines(r.parts).map(esc).join(" · ")}</small></div></div>`);
    const c = filter && comp(filter);
    const list = paged(`maint-${filter || ""}`, items, { cols: 2, rowH: 104 });
    return {
      title: c ? `${esc(tr(c.title))} · ${esc(L("maintenance"))}` : esc(L("maintenance")),
      up: c ? `#/component/${filter}` : "#/",
      html: `<div class="fill">${list.html}</div>`, after: list.mount,
    };
  }

  function parts() {
    const rows = (M.spare_parts || []).slice().sort((a, b) => String(a.part_no).localeCompare(String(b.part_no)));
    const items = rows.map((p) => `<div class="mrow"><div class="when">${esc(p.part_no)}
        ${assembly(p.component) ? `<span class="tag" style="--c:${color(p.component)}">${esc(tr(comp(p.component).title))}</span>` : ""}</div>
        <div><b>${esc(tr(p.description))}</b>${tr(p.interval) ? `<small>${esc(L("interval"))}: ${esc(tr(p.interval))}</small>` : ""}</div></div>`);
    const list = paged("parts", items, { cols: 2, rowH: 92 });
    return { title: esc(L("spare_parts")), up: "#/", html: `<div class="fill">${list.html}</div>`, after: list.mount };
  }

  function notFound() {
    return { title: t("unknown"), up: "#/", html: `<div class="empty"><h2>${t("unknown")}</h2>
      <button class="btn primary" data-go="#/">${t("help")}</button></div>` };
  }

  // --- router --------------------------------------------------------------
  function route() {
    const parts_ = location.hash.replace(/^#\/?/, "").split("/").filter(Boolean).map(decodeURIComponent);
    const [a, b, c, d] = parts_;
    if (!a) return home();
    if (a === "faults") return faultSearch();
    if (a === "fault" && b) return faultPage(b);
    if (a === "component" && b) return componentPage(b, c, d);
    if (a === "maintenance") return maintenance();
    if (a === "parts") return parts();
    return notFound();
  }

  function render() {
    const r = route();
    document.getElementById("title").innerHTML = r.title;
    const up = document.getElementById("upBtn");
    up.hidden = !r.up;
    up.onclick = () => go(r.up);
    document.getElementById("homeBtn").hidden = !r.up;
    view.innerHTML = r.html;
    if (r.after) r.after();
  }

  // one tap handler for links and pictures
  view.addEventListener("click", (e) => {
    if (swiped) return;
    const link = e.target.closest("[data-go]");
    if (link) { go(link.dataset.go); return; }
    const fig = e.target.closest(".pic");
    if (fig) zoom(fig);
  });

  function zoom(fig) {
    const z = document.getElementById("zoom");
    z.innerHTML = fig.innerHTML + `<div class="hint">${t("zoom")}</div>`;
    z.hidden = false;
  }
  document.getElementById("zoom").onclick = (e) => { e.currentTarget.hidden = true; e.currentTarget.innerHTML = ""; };

  document.getElementById("homeBtn").innerHTML = icon("home");
  document.getElementById("homeBtn").onclick = () => go("#/");
  document.getElementById("upBtn").innerHTML = icon("left");
  document.getElementById("langs").innerHTML = LANGS.length < 2 ? "" : LANGS.map((l) =>
    `<button class="${l === lang ? "on" : ""}" data-lang="${l}">${l.toUpperCase()}</button>`).join("");
  for (const b of document.querySelectorAll("#langs button")) {
    b.onclick = () => { location.href = location.pathname + "?lang=" + b.dataset.lang + location.hash; };
  }
  let resizeTimer = null;
  addEventListener("resize", () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(render, 150); });
  addEventListener("hashchange", render);
  addEventListener("contextmenu", (e) => e.preventDefault());
  render();
})();
